local KeyCodes, TableUtil = ...local CustomizeControlPrompt = {}local BND_MESSAGE = "bnd_message"local BND_OVERLAY_FOOTER = "bnd_overlay_footer"local ACT_KEY_PRESS = "act_key_press"local ACT_MOUSE_CLICK = "act_mouse_click"local ACT_CLOSE = "act_close"local keyBoardControllerId = 4local customSaveSlot = 5local customPendingSaveSlot = 100local keyCodeProcessed = falselocal showingMessagePopup = falsefunction CustomizeControlPrompt:new(init)  print("[CustomizeControlPrompt]: new()")  keyCodeProcessed = false  showingMessagePopup = false  local o = init or {}  setmetatable(o, self)  self.__index = self  o.services = {    CustomizationService = o.api("FifaCustomizationService")  }  o.control = {    currentKey = o.data.currentKey,    actionId = o.data.actionId  }  o.controlChangeHandler = o.data.controlChangeHandler  o.message = o.loc.LocalizeString("LTXT_PRESS_BUTTON_OR_KEY_FOR_ACTION")  o.footer = {}  TableUtil.print(o.control)  o.im.Subscribe(BND_MESSAGE, function()    o:_publishMessage()  end  )  o.im.Subscribe(BND_OVERLAY_FOOTER, function()    o:_publishFooter(false)  end  )  o.im.RegisterAction(ACT_KEY_PRESS, function(actionName, keyCode)    o:processKeyPress(keyCode)  end  )  o.im.RegisterAction(ACT_MOUSE_CLICK, function(actionName, buttonIdx)    o:processMouseClick(buttonIdx)  end  )  o.im.RegisterAction(ACT_CLOSE, function(actionName)    o:onCloseButtonClick()  end  )  return oendfunction CustomizeControlPrompt:processKeyPress(keyCode)  if keyCodeProcessed == false and showingMessagePopup == false then    print("[CustomizeControlPrompt]: processKeyPress(" .. (keyCode or "nil") .. ")")    print("self.control.currentKey: ", self.control.currentKey)    print("self.control.actionId: ", self.control.actionId - 1)    local resultSetKeyboardButton = self.services.CustomizationService.SetKeyboardButton(self.control.currentKey, self.control.actionId - 1, keyCode)    if resultSetKeyboardButton.RESULT ~= "" and resultSetKeyboardButton.RESULT ~= "MouseInputError" and resultSetKeyboardButton.RESULT ~= "KeyboardInputError" and resultSetKeyboardButton.RESULT ~= "KeyboardInputAlreadyInUse" then      self.services.CustomizationService.SetCustomControllerSlot(keyBoardControllerId, customSaveSlot)      self.services.CustomizationService.SetKeyboardConfiguration(keyBoardControllerId, customPendingSaveSlot)      if self.controlChangeHandler ~= nil then        self.controlChangeHandler()      end      self.nav.Event(nil, "evt_hide_overlay")    elseif keyCode == KeyCodes.KEYCODE_ESC then      self.nav.Event(nil, "evt_hide_overlay")    elseif resultSetKeyboardButton.RESULT == "MouseInputError" then      showingMessagePopup = true      self.message = self.loc.LocalizeString("LTXT_CONTROLS_INVALID_KEY")      self:_publishMessage()      self:_publishFooter(true)    elseif resultSetKeyboardButton.RESULT == "KeyboardInputError" then      showingMessagePopup = true      self.message = self.loc.LocalizeString("LTXT_CONTROLS_INVALID")      self:_publishMessage()      self:_publishFooter(true)    elseif resultSetKeyboardButton.RESULT == "KeyboardInputAlreadyInUse" then      showingMessagePopup = true      self.message = self.loc.LocalizeString("LTXT_SETTINGS_CONTROLS_IN_USE")      self:_publishMessage()      self:_publishFooter(true)    else      showingMessagePopup = true      self.message = self.loc.LocalizeString("LTXT_CONTROLS_INVALID")      self:_publishMessage()      self:_publishFooter(true)    end    keyCodeProcessed = true  else    print("[CustomizeControlPrompt]: IGNORING processKeyPress(" .. (keyCode or "nil") .. ")")    self.nav.Event(nil, "evt_hide_overlay")    showingMessagePopup = false  endendfunction CustomizeControlPrompt:processMouseClick(buttonIdx)  print("[CustomizeControlPrompt]: processMouseClick(" .. (buttonIdx or "nil") .. ")")  if showingMessagePopup == false then    print("self.control.currentKey: ", self.control.currentKey)    print("self.control.actionId: ", self.control.actionId - 1)    local resultSetKeyboardButton = self.services.CustomizationService.SetKeyboardButton(self.control.currentKey, self.control.actionId - 1)    if resultSetKeyboardButton.RESULT ~= "" and resultSetKeyboardButton.RESULT ~= "MouseInputError" and resultSetKeyboardButton.RESULT ~= "KeyboardInputError" and resultSetKeyboardButton.RESULT ~= "KeyboardInputAlreadyInUse" then      self.services.CustomizationService.SetCustomControllerSlot(keyBoardControllerId, customSaveSlot)      self.services.CustomizationService.SetKeyboardConfiguration(keyBoardControllerId, customPendingSaveSlot)      if self.controlChangeHandler ~= nil then        self.controlChangeHandler()      end      self.nav.Event(nil, "evt_hide_overlay")    elseif resultSetKeyboardButton.RESULT == "MouseInputError" then      showingMessagePopup = true      self.message = self.loc.LocalizeString("LTXT_CONTROLS_INVALID")      self:_publishMessage()      self:_publishFooter(true)    elseif resultSetKeyboardButton.RESULT == "KeyboardInputError" then      showingMessagePopup = true      self.message = self.loc.LocalizeString("LTXT_CONTROLS_INVALID_MOUSE")      self:_publishMessage()      self:_publishFooter(true)    elseif resultSetKeyboardButton.RESULT == "KeyboardInputAlreadyInUse" then      showingMessagePopup = true      self.message = self.loc.LocalizeString("LTXT_SETTINGS_CONTROLS_IN_USE")      self:_publishMessage()      self:_publishFooter(true)    else      showingMessagePopup = true      self.message = self.loc.LocalizeString("LTXT_CONTROLS_INVALID")      self:_publishMessage()      self:_publishFooter(true)    end  else    self.nav.Event(nil, "evt_hide_overlay")  endendfunction CustomizeControlPrompt:onCloseButtonClick()  self.nav.Event(nil, "evt_hide_overlay")endfunction CustomizeControlPrompt:_publishMessage()  print("[CustomizeControlPrompt]: _publishMessage()")  self.im.Publish(BND_MESSAGE, self.message)endfunction CustomizeControlPrompt:_publishFooter(initFooter)  if initFooter == true then    self.footer = {      {        label = self.loc.LocalizeString("LTXT_SOC_CLOSE"),        icon = "$FooterIconNo",        clickAction = ACT_CLOSE      }    }  end  self.im.Publish(BND_OVERLAY_FOOTER, self.footer)endfunction CustomizeControlPrompt:finalize()  print("[CustomizeControlPrompt]: finalize()")  self.control = nil  self.controlChangeHandler = nil  self.im.Unsubscribe(BND_MESSAGE)  self.im.Unsubscribe(BND_OVERLAY_FOOTER)  self.im.UnregisterAction(ACT_KEY_PRESS)  self.im.UnregisterAction(ACT_MOUSE_CLICK)  self.im.UnregisterAction(ACT_CLOSE)endreturn CustomizeControlPrompt